/* ============================================
   LearnForge — Global Styles
   Design System: Modern, Bold, Professional
   Primary: #000000 | Accent: #E6FF32 | Deep: #7F2A23
   Typography: Plus Jakarta Sans
   ============================================ */

@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:ital,wght@0,400;0,500;0,600;0,700;0,800;1,400&display=swap');

/* CSS Variables */
:root {
  --primary: #000000;
  --accent: #E6FF32;
  --deep: #7F2A23;
  --bg: #FFFFFF;
  --bg-alt: #F8F9FB;
  --surface: #FFFFFF;
  --text: #0F172A;
  --text-secondary: #475569;
  --text-muted: #94A3B8;
  --border: #E2E8F0;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.06);
  --shadow-lg: 0 12px 40px rgba(0,0,0,0.08);
  --transition: 200ms cubic-bezier(0.4, 0, 0.2, 1);
  --max-width: 1280px;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img {
  max-width: 100%;
  display: block;
}

a {
  text-decoration: none;
  color: inherit;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* Container */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

@media (min-width: 768px) {
  .container {
    padding: 0 40px;
  }
}

@media (min-width: 1024px) {
  .container {
    padding: 0 64px;
  }
}

/* ============================================
   NAVIGATION
   ============================================ */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border);
  transition: var(--transition);
}

.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 68px;
}

@media (min-width: 768px) {
  .nav-inner {
    padding: 0 40px;
  }
}

@media (min-width: 1024px) {
  .nav-inner {
    padding: 0 64px;
  }
}

.nav-logo {
  font-weight: 800;
  font-size: 1.35rem;
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-logo .logo-dot {
  width: 10px;
  height: 10px;
  background: var(--accent);
  border-radius: 50%;
  display: inline-block;
}

.nav-links {
  display: none;
  align-items: center;
  gap: 32px;
}

@media (min-width: 1024px) {
  .nav-links {
    display: flex;
  }
}

.nav-links a {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-secondary);
  transition: var(--transition);
  position: relative;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text);
}

.nav-links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent);
  border-radius: 1px;
}

.nav-cta {
  display: none;
}

@media (min-width: 1024px) {
  .nav-cta {
    display: flex;
    align-items: center;
    gap: 16px;
  }
}

.nav-cta a {
  font-size: 0.875rem;
  font-weight: 600;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 700;
  transition: var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--primary);
  color: #fff;
}

.btn-primary:hover {
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background: var(--accent);
  color: var(--primary);
}

.btn-accent:hover {
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  background: transparent;
  color: var(--text);
  border: 1.5px solid var(--border);
}

.btn-outline:hover {
  border-color: var(--text);
}

.btn-sm {
  padding: 8px 18px;
  font-size: 0.8rem;
}

/* Mobile menu */
.nav-mobile-toggle {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.nav-mobile-toggle span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--text);
  transition: var(--transition);
}

@media (min-width: 1024px) {
  .nav-mobile-toggle {
    display: none;
  }
}

.nav-mobile {
  display: none;
  position: absolute;
  top: 68px;
  left: 0;
  right: 0;
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  padding: 16px 24px 24px;
  flex-direction: column;
  gap: 8px;
}

.nav-mobile.open {
  display: flex;
}

.nav-mobile a {
  padding: 10px 0;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border);
}

.nav-mobile a:last-child {
  border-bottom: none;
}

.nav-mobile .btn {
  margin-top: 8px;
  width: 100%;
}

/* ============================================
   SECTIONS
   ============================================ */
.section {
  padding: 80px 0;
}

@media (min-width: 768px) {
  .section {
    padding: 100px 0;
  }
}

.section-alt {
  background: var(--bg-alt);
}

.section-header {
  text-align: center;
  max-width: 720px;
  margin: 0 auto 56px;
}

.section-header h2 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.15;
  margin-bottom: 16px;
}

.section-header p {
  font-size: 1.1rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ============================================
   HERO
   ============================================ */
.hero {
  padding-top: 140px;
  padding-bottom: 80px;
  background: var(--bg);
  position: relative;
  overflow: hidden;
}

.hero-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  gap: 48px;
  align-items: center;
}

@media (min-width: 768px) {
  .hero-inner {
    padding: 0 40px;
  }
}

@media (min-width: 1024px) {
  .hero-inner {
    padding: 0 64px;
    grid-template-columns: 1fr 1fr;
    gap: 64px;
  }
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  padding: 6px 14px;
  border-radius: 100px;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-secondary);
  margin-bottom: 20px;
}

.hero-badge .dot {
  width: 8px;
  height: 8px;
  background: var(--accent);
  border-radius: 50%;
}

.hero h1 {
  font-size: clamp(2.2rem, 5vw, 3.5rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1.1;
  margin-bottom: 20px;
}

.hero p {
  font-size: 1.1rem;
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 32px;
  max-width: 520px;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 32px;
}

/* Hero tabs */
.hero-tabs {
  display: inline-flex;
  background: var(--bg-alt);
  border-radius: 100px;
  padding: 4px;
  gap: 4px;
  margin-bottom: 24px;
}

.hero-tab {
  padding: 8px 18px;
  border-radius: 100px;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--text-secondary);
  transition: var(--transition);
}

.hero-tab.active {
  background: var(--primary);
  color: #fff;
}

.hero-preview {
  position: relative;
  border-radius: var(--radius-xl);
  overflow: hidden;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-lg);
  min-height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-preview-content {
  display: none;
  width: 100%;
  padding: 32px;
}

.hero-preview-content.active {
  display: block;
}

.preview-card {
  background: var(--surface);
  border-radius: var(--radius-md);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border);
}

.preview-card h4 {
  font-size: 0.9rem;
  font-weight: 700;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.preview-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px solid var(--border);
}

.preview-row:last-child {
  border-bottom: none;
}

.preview-avatar {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background: linear-gradient(135deg, var(--accent), #c8e600);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.75rem;
  color: var(--primary);
  flex-shrink: 0;
}

.preview-info {
  flex: 1;
  min-width: 0;
}

.preview-info .name {
  font-size: 0.8rem;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.preview-info .meta {
  font-size: 0.7rem;
  color: var(--text-muted);
}

.preview-badge {
  padding: 4px 10px;
  border-radius: 100px;
  font-size: 0.7rem;
  font-weight: 700;
  background: #ECFDF5;
  color: #059669;
}

/* Student view preview */
.student-preview {
  text-align: center;
}

.student-preview .course-thumb {
  width: 100%;
  height: 140px;
  background: linear-gradient(135deg, #1e293b, #334155);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-weight: 700;
  font-size: 1rem;
  margin-bottom: 16px;
}

.student-preview h4 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.student-preview p {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-bottom: 16px;
}

.progress-bar {
  width: 100%;
  height: 6px;
  background: var(--border);
  border-radius: 3px;
  overflow: hidden;
}

.progress-bar .fill {
  height: 100%;
  width: 65%;
  background: var(--accent);
  border-radius: 3px;
}

/* ============================================
   STATS BAR
   ============================================ */
.stats-bar {
  background: var(--primary);
  color: #fff;
  padding: 40px 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: 32px;
  text-align: center;
}

@media (min-width: 640px) {
  .stats-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.stat-item h3 {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--accent);
  margin-bottom: 4px;
}

.stat-item p {
  font-size: 0.9rem;
  color: rgba(255,255,255,0.7);
  font-weight: 500;
}

/* ============================================
   PRODUCT CARDS
   ============================================ */
.products-grid {
  display: grid;
  grid-template-columns: repeat(1, 1fr);
  gap: 24px;
}

@media (min-width: 640px) {
  .products-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .products-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.product-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: var(--transition);
  cursor: pointer;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: transparent;
}

.product-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--bg-alt);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
}

.product-icon svg {
  width: 24px;
  height: 24px;
  stroke: var(--primary);
}

.product-card h3 {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.product-card p {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ============================================
   WHY CHOOSE US — TABS
   ============================================ */
.why-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
  margin-bottom: 48px;
}

.why-tab {
  padding: 10px 20px;
  border-radius: 100px;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--text-secondary);
  background: var(--bg-alt);
  border: 1.5px solid transparent;
  transition: var(--transition);
  cursor: pointer;
}

.why-tab:hover {
  border-color: var(--border);
}

.why-tab.active {
  background: var(--primary);
  color: #fff;
}

.why-content {
  display: none;
  animation: fadeIn 300ms ease;
}

.why-content.active {
  display: block;
}

.why-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 768px) {
  .why-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

.why-feature {
  display: flex;
  gap: 16px;
  padding: 24px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
}

.why-feature .check {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.why-feature .check svg {
  width: 14px;
  height: 14px;
  stroke: var(--primary);
  stroke-width: 3;
}

.why-feature h4 {
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 4px;
}

.why-feature p {
  font-size: 0.875rem;
  color: var(--text-secondary);
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ============================================
   TESTIMONIALS CAROUSEL
   ============================================ */
.testimonials-wrap {
  position: relative;
  overflow: hidden;
}

.testimonials-track {
  display: flex;
  transition: transform 400ms cubic-bezier(0.4, 0, 0.2, 1);
}

.testimonial-card {
  flex: 0 0 100%;
  padding: 0 12px;
}

@media (min-width: 768px) {
  .testimonial-card {
    flex: 0 0 50%;
  }
}

@media (min-width: 1024px) {
  .testimonial-card {
    flex: 0 0 33.333%;
  }
}

.testimonial-inner {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px;
  height: 100%;
}

.testimonial-tag {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 100px;
  font-size: 0.7rem;
  font-weight: 700;
  background: var(--accent);
  color: var(--primary);
  margin-bottom: 16px;
}

.testimonial-quote {
  font-size: 1rem;
  line-height: 1.6;
  margin-bottom: 24px;
  color: var(--text);
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.testimonial-author .avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), #c8e600);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.8rem;
  color: var(--primary);
}

.testimonial-author .name {
  font-size: 0.875rem;
  font-weight: 700;
}

.testimonial-author .company {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 32px;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1.5px solid var(--border);
  background: var(--surface);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
}

.carousel-btn:hover {
  background: var(--primary);
  border-color: var(--primary);
}

.carousel-btn:hover svg {
  stroke: #fff;
}

.carousel-btn svg {
  width: 18px;
  height: 18px;
  stroke: var(--text);
  stroke-width: 2;
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 16px;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--border);
  transition: var(--transition);
  cursor: pointer;
}

.carousel-dot.active {
  background: var(--primary);
  width: 24px;
  border-radius: 4px;
}

/* ============================================
   PRICING
   ============================================ */
.pricing-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
  max-width: 900px;
  margin: 0 auto;
}

@media (min-width: 768px) {
  .pricing-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.pricing-card {
  background: var(--surface);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: var(--transition);
}

.pricing-card.featured {
  border-color: var(--primary);
  position: relative;
}

.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
  padding: 4px 14px;
  border-radius: 100px;
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
}

.pricing-card h3 {
  font-size: 1.1rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.pricing-card .price {
  font-size: 2.2rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 4px;
}

.pricing-card .price-note {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-bottom: 20px;
}

.pricing-card ul {
  margin-bottom: 24px;
}

.pricing-card ul li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 0;
  font-size: 0.875rem;
  color: var(--text-secondary);
}

.pricing-card ul li svg {
  width: 16px;
  height: 16px;
  stroke: var(--accent);
  stroke-width: 3;
  flex-shrink: 0;
}

.pricing-card .btn {
  width: 100%;
}

/* ============================================
   INTEGRATIONS
   ============================================ */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

@media (min-width: 640px) {
  .integrations-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (min-width: 768px) {
  .integrations-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

@media (min-width: 1024px) {
  .integrations-grid {
    grid-template-columns: repeat(6, 1fr);
  }
}

.integration-item {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 20px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-secondary);
  transition: var(--transition);
}

.integration-item:hover {
  border-color: var(--text);
  color: var(--text);
}

.integration-item svg {
  width: 20px;
  height: 20px;
  stroke: var(--text-secondary);
  flex-shrink: 0;
}

/* ============================================
   FAQ ACCORDION
   ============================================ */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 0;
  font-size: 1rem;
  font-weight: 700;
  text-align: left;
  color: var(--text);
  transition: var(--transition);
}

.faq-question:hover {
  color: var(--text-secondary);
}

.faq-question svg {
  width: 20px;
  height: 20px;
  stroke: var(--text);
  stroke-width: 2;
